import{_ as i,a as n,c as a,ac as l}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 本册介绍","description":"适合英语初学者或希望系统重建基础的人。先熟悉字母和基本音标；不要求已掌握时态，但需能把简单单词读出并辨认主语与动作。","frontmatter":{"title":"第一册：英语初阶 · 本册介绍","description":"适合英语初学者或希望系统重建基础的人。先熟悉字母和基本音标；不要求已掌握时态，但需能把简单单词读出并辨认主语与动作。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"适合英语初学者或希望系统重建基础的人。先熟悉字母和基本音标；不要求已掌握时态，但需能把简单单词读出并辨认主语与动作。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"新概念英语：经典版四册学习目录","link":"/life/english/new-concept/overview"},"next":{"text":"第一册：英语初阶 · 全册课程目录","link":"/life/english/new-concept/book-1/contents"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"新概念英语：经典版四册学习目录","link":"/life/english/new-concept/overview"},"next":{"text":"第一册：英语初阶 · 全册课程目录","link":"/life/english/new-concept/book-1/contents"}},"headers":[],"relativePath":"life/english/new-concept/book-1/overview.md","filePath":"life/english/new-concept/book-1/overview.md"}'),o={name:"life/english/new-concept/book-1/overview.md"};function t(r,e,c,s,h,p){return n(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-本册介绍" tabindex="-1">第一册：英语初阶 · 本册介绍 <a class="header-anchor" href="#第一册-英语初阶-·-本册介绍" aria-label="Permalink to &quot;第一册：英语初阶 · 本册介绍&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>第一册以生活场景建立基础句型，从确认身份和物品，逐步走向时间、经历、转述和简单复合句。学习重点不是把每一句译成中文，而是能听出信息、问清问题并独立回应。经典版保留144个课号，其中相邻奇偶课形成情景学习与句型训练的配合。本栏目每个课号单独设页，提供原创例句、练习及解析；配套课继续使用相同知识点，但更换例句和作答任务。完成一课后应能不看答案重新表达，再回看语法解释自己为什么这样说。</p><h2 id="版本与内容范围" tabindex="-1">版本与内容范围 <a class="header-anchor" href="#版本与内容范围" aria-label="Permalink to &quot;版本与内容范围&quot;">​</a></h2><p>First Things First；经典版 144 课。本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习前提" tabindex="-1">学习前提 <a class="header-anchor" href="#学习前提" aria-label="Permalink to &quot;学习前提&quot;">​</a></h2><p>适合英语初学者或希望系统重建基础的人。先熟悉字母和基本音标；不要求已掌握时态，但需能把简单单词读出并辨认主语与动作。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能完成问候、介绍、购物、问路与预约等基本交际任务。</li><li>能区分主要基础时态、情态表达和主动被动。</li><li>能使用基本关系从句、宾语从句和条件句组织较长信息。</li><li>能通过原创练习解释自己的错误，而不只对照答案。</li></ul><h2 id="学习方法与进度" tabindex="-1">学习方法与进度 <a class="header-anchor" href="#学习方法与进度" aria-label="Permalink to &quot;学习方法与进度&quot;">​</a></h2><p>建议每次以相邻奇偶两课为一组，先读情景课，再遮住讲解完成配套练习。每次分为词汇与语法、听说、书面自测三个环节；学习时间根据基础调整，不以固定天数承诺效果。每24课完成一次单元复习。错误若集中在主谓一致或助动词，先回看相应规则，再继续新内容；不要为赶进度跳过偶数课。</p><h2 id="单元入口" tabindex="-1">单元入口 <a class="header-anchor" href="#单元入口" aria-label="Permalink to &quot;单元入口&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-1/unit-01/overview">学习单元 1：身份、物品与基本问答</a></li><li><a href="/life/english/new-concept/book-1/unit-02/overview">学习单元 2：空间、眼前动作与基本需求</a></li><li><a href="/life/english/new-concept/book-1/unit-03/overview">学习单元 3：日常规律、时间与过去状态</a></li><li><a href="/life/english/new-concept/book-1/unit-04/overview">学习单元 4：过去事件、完成结果与未来安排</a></li><li><a href="/life/english/new-concept/book-1/unit-05/overview">学习单元 5：转述、程度比较与过去先后</a></li><li><a href="/life/english/new-concept/book-1/unit-06/overview">学习单元 6：关系从句、推断、条件与被动</a></li></ul><h2 id="目录核对来源" tabindex="-1">目录核对来源 <a class="header-anchor" href="#目录核对来源" aria-label="Permalink to &quot;目录核对来源&quot;">​</a></h2><ul><li><a href="https://zy.21cnjy.com/8921710" target="_blank" rel="noopener noreferrer">第一册144课目录核对（21世纪教育网）</a></li><li><a href="https://eol.nju.edu.cn/courses/xinke1-xdf.html" target="_blank" rel="noopener noreferrer">第一册课程目录交叉核对</a></li><li><a href="https://www.fltrp.com/" target="_blank" rel="noopener noreferrer">外语教学与研究出版社：版本与配套资料入口</a></li></ul><p><a href="/life/english/new-concept/overview">返回系列介绍</a></p>',17)])])}const k=i(o,[["render",t]]);export{d as __pageData,k as default};
